#!/usr/bin/env python3
"""Macros for the Tier-T strong-probe paragraph (wave22). Values from analyse_strong_v1."""
import subprocess, re, pathlib
out = subprocess.run(["python3","scripts/analyse_strong_v1.py"],capture_output=True,text=True).stdout
rows = {}
for line in out.splitlines():
    m = re.match(r"(Qwen2\.5|Qwen3|Qwen2-Audio|Nemotron)\s+[\d.]+\s+\S+\s+([+-]\d+\.\d)\s+\[\s*([+-]\d+\.\d),\s*([+-]\d+\.\d)\]", line)
    if m: rows[m.group(1)] = (m.group(2), m.group(3), m.group(4))
assert len(rows) == 4, rows
p = pathlib.Path("paper/auto_strong.tex")
p.write_text(
    "% generated by scripts/gen_strong_macros_v1.py -- do not edit\n"
    # NOT computed here. 0.897 is the probe's out-of-fold accuracy, recorded in log_v1.md
    # ("probe: both CLAP embeddings+similarity+class one-hot logistic, fold cross-fitted, OOF
    # 0.897"). Re-running this script re-emits the constant; it does not re-verify it.
    "\\newcommand{\\StrongAcc}{0.897}\n"
    f"\\newcommand{{\\StrongQTwoA}}{{{rows['Qwen2-Audio'][0]}}}\n"
    f"\\newcommand{{\\StrongQTwoALo}}{{{rows['Qwen2-Audio'][1]}}}\n"
    f"\\newcommand{{\\StrongQTwoAHi}}{{{rows['Qwen2-Audio'][2]}}}\n"
    f"\\newcommand{{\\StrongQTwoFive}}{{{rows['Qwen2.5'][0]}}}\n"
    f"\\newcommand{{\\StrongQThree}}{{{rows['Qwen3'][0]}}}\n"
    f"\\newcommand{{\\StrongNemo}}{{{rows['Nemotron'][0]}}}\n")
print(p.read_text())
